import os, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print(sorted(G.keys()))

import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()

# Need to find grids in the actual JSONL message bodies
# Grid headers are like "Demo pair 1 input (26x21):" or "Test input (26x15):"
# These appear in the text content of messages

G = {}

def extract_grids(text):
    lines = text.replace('\\n', '\n').split('\n')

    for i, line in enumerate(lines):
        if re.match(r'(Demo pair \d+ (?:input|output)|Test input) \(\d+x\d+\):\n?', line):
            # Found a header, collect next N lines that are grids
            match = re.match(r'(.+) \((\d+)x(\d+)\):\n?', line)
            if match:
                name, h, w = match.group(1), int(match.group(2)), int(match.group(3))

                rows = []
                j = i + 1
                while len(rows) < h and j < len(lines):
                    row_line = lines[j].strip()
                    # Check if it's a grid row (numbers separated by spaces)
                    if re.match(r'^\d+\s+\d+', row_line):
                        parts = [int(x) for x in row_line.split()]
                        if len(parts) == w:
                            rows.append(parts)
                        else:
                            # Wrong width, might be comment - skip
                            pass
                    j += 1

                if rows and all(len(r) == w for r in rows):
                    G[name] = rows
                    print(f"Parsed {name}: {h}x{w}")
                else:
                    print(f"Failed to parse {name}")

# Find all message blocks containing grids
# The JSON has nested strings with newlines escaped as \\n
for m in re.finditer(r'"content":\[(.*?)\]', t, re.DOTALL):
    content_str = m.group(1)
    extract_grids(content_str)

print(f"\nTotal grids found: {len(G)}")

